import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "../../shared/cn.js";

export interface PaginationProps {
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  /** Override nav container classes */
  className?: string;
  /** Override individual page button classes */
  buttonClassName?: string;
  /** Override active page button classes */
  activeButtonClassName?: string;
}

/**
 * Build the visible page list with ellipsis markers.
 * Pure logic — exported for testing.
 */
export function buildPageList(
  currentPage: number,
  totalPages: number,
  delta = 2,
): (number | "...")[] {
  if (totalPages <= 0) return [];
  const safeDelta = Math.max(0, delta);
  const pages: (number | "...")[] = [];
  for (let i = 1; i <= totalPages; i++) {
    if (
      i === 1 ||
      i === totalPages ||
      (i >= currentPage - safeDelta && i <= currentPage + safeDelta)
    ) {
      pages.push(i);
    } else if (pages[pages.length - 1] !== "...") {
      pages.push("...");
    }
  }
  return pages;
}

const baseBtn =
  "focus-visible:ring-ring inline-flex h-9 w-9 items-center justify-center rounded-lg border text-sm transition-all focus-visible:ring-2 focus-visible:outline-none disabled:pointer-events-none disabled:opacity-50";

export function Pagination({
  currentPage,
  totalPages,
  onPageChange,
  className,
  buttonClassName,
  activeButtonClassName,
}: PaginationProps) {
  if (totalPages <= 1) return null;

  const pages = buildPageList(currentPage, totalPages);

  return (
    <nav
      aria-label={`Pagination, page ${currentPage} of ${totalPages}`}
      className={cn("flex items-center justify-center gap-2", className)}
    >
      <button
        type="button"
        className={cn(
          baseBtn,
          "border-border text-muted-foreground hover:bg-muted hover:text-foreground",
          buttonClassName,
        )}
        disabled={currentPage <= 1}
        onClick={() => {
          onPageChange(Math.max(1, currentPage - 1));
        }}
        aria-label="Previous page"
      >
        <ChevronLeft className="h-4 w-4" aria-hidden="true" />
      </button>

      {pages.map((page, i) =>
        page === "..." ? (
          <span
            key={`e-${i}`}
            aria-hidden="true"
            className="text-muted-foreground flex h-9 w-9 items-center justify-center"
          >
            ...
          </span>
        ) : (
          <button
            key={page}
            type="button"
            className={cn(
              baseBtn,
              page === currentPage
                ? cn(
                    "border-primary bg-primary text-primary-foreground scale-105 font-bold shadow-sm",
                    activeButtonClassName,
                  )
                : cn(
                    "border-border text-muted-foreground hover:border-muted-foreground/30 hover:bg-muted hover:text-foreground",
                    buttonClassName,
                  ),
            )}
            onClick={() => {
              onPageChange(page);
            }}
            aria-current={page === currentPage ? "page" : undefined}
          >
            {page}
          </button>
        ),
      )}

      <button
        type="button"
        className={cn(
          baseBtn,
          "border-border text-muted-foreground hover:bg-muted hover:text-foreground",
          buttonClassName,
        )}
        disabled={currentPage >= totalPages}
        onClick={() => {
          onPageChange(Math.min(totalPages, currentPage + 1));
        }}
        aria-label="Next page"
      >
        <ChevronRight className="h-4 w-4" aria-hidden="true" />
      </button>
    </nav>
  );
}
